# 把《倍数之和与快速幂-012与013排错》登记进索引
$ErrorActionPreference = 'Stop'
$p = 'D:\lenovo\chat_with_deepseek_harness\讲义\00-知识索引与复习路线图.md'
$all = (Get-ChildItem 'D:\lenovo\chat_with_deepseek_harness\讲义\*.md').Count
$expect = $all - 2
$lines = [System.Collections.Generic.List[string]](Get-Content -LiteralPath $p -Encoding UTF8)
$lines[4] = $lines[4] -replace '收录：\*\*\d+ 份\*\*', "收录：**$expect 份**"

$idx = -1
for ($i = 0; $i -lt $lines.Count; $i++) {
    if ($lines[$i].StartsWith('| `倍数之和-ans没清零导致2341`')) { $idx = $i }
}
if ($idx -lt 0) { throw '找不到锚点行：倍数之和-ans没清零导致2341' }

$lec = '| `倍数之和与快速幂-012与013排错` | **回答"012.cpp 和 013.cpp 问题出在哪里"**：**012（小于 n 的 3 或 5 的倍数之和，T ≤ 1e5, n ≤ 1e9）——你上次的 bug 已修对**（`ans = 0` 挪进循环 ✅，实测 `10/100/10` → `23/2318/23` 全对），**剩下的问题是必然 TLE**：`for(i=3;i<n;++i)` 在 `T≤1e5, n≤1e9` 下约 **1e14 次**循环（本机实测单组 `n=1e8` 要 **83 ms**，外推 ≈ **23 小时**）⇒ 改为**等差数列 + 容斥**：`m=(n-1)/k`（**"小于 n"必须减 1**）、`S(k)=k·m(m+1)/2`、`ans=S(3)+S(5)−S(15)`；实测样例 `23/2318` ✅、**vs 暴力枚举 400 组不一致 0** ✅、极限 `T=1e5,n=1e9` **64 ms**（答案 ≈2.33e17 必须 `long long`）。**013（a^b mod m，1 ≤ a,b,m ≤ 2^63）——不是笔误，是做法错**：`pow(a,b)` 返回 **double**（仅 53 位有效位，精确整数上限 2^53≈9e15），大幂丢精度、超 1.8e308 变 `inf`，转 `long long` 是 **UB**；**实测 `2 63 1000000007` 正确是 `291172004`，你的输出 `-291172004`（绝对值对、符号错 = 高位溢出后被符号位解释的典型指纹）**；**随机 180 组 vs Python `pow(a,b,m)`：你的原码错 180/180 ✘、修正版 0/180 ✅**。正解 = **快速幂**（二进制拆指数，`O(log b)` ≤ 63 次迭代、每次乘法后取模），⚠️ 另有两个隐藏坑：**两数都 < m ≤ 2^63 时 `res*a ≈ 1.7e38 ≫ LLONG_MAX`** ⇒ 乘法必须用 `__int128` 中转；**`res = 1 % m` 不能写 `1`**（`m=1` 时答案必须是 0）。并提炼四条可迁移经验（`n ≤ 1e9` 别写 `for`／看到 `a^b` 先估数量级／`pow` 是浮点函数不是整数幂／乘法比加法更容易溢出），并把自检三问扩成四问：**「最大数据我试过吗？」**（012 样例太小、013 样例 `2^10` 太小 —— 都是"样例全对但规模/范围全错"）。手册新增 **§6.15 快速幂与乘法防溢出**；讲义含 6 题自查（含"为什么答案只差一个负号"的机理解释） |'
$lines.Insert($idx + 1, $lec)

$log = '| 2026-09-27 | +`倍数之和与快速幂-012与013排错`（**线 5**，回答"012.cpp 和 013.cpp 问题出在哪里"）：**012** 是用户上次问过的"3 或 5 的倍数之和"，**`ans` 初始化已修对**，但 **`for(i=3;i<n;++i)` 必然 TLE**（`T=1e5, n=1e9` ⇒ ≈1e14 次；实测单组 `n=1e8` **83 ms**）⇒ 正解**等差数列 + 容斥** O(1)/组（`S(k)=k·m(m+1)/2`、`m=(n-1)/k`），实测样例全对、vs 暴力 400 组 0 不一致、极限 **64 ms**、答案 2.33e17 需 `long long`。**013** 是 `a^b mod m`（`≤2^63`），**做法性错误**：`pow` 返回 double（精度只到 2^53、可产生 inf），转 `long long` 是 UB —— 实测 `2 63 1000000007` 正确 `291172004`、用户输出 **-291172004**（"只差一个负号"= 高位溢出的指纹）；**随机 180 组 vs Python `pow(a,b,m)`：原码 180/180 全错、修正版 0/180 ✅**。正解**快速幂**，另两个坑：**乘法用 `__int128` 防溢出**（`(2^63)²≈1.7e38`）、**`res=1%m` 不能省**（`m=1`）。手册新增 **§6.15 快速幂与乘法防溢出**（并顺号整理 §6.13/§6.14/§6.15 与索引引用）后重跑 docx；讲义含"样例全对但规模/范围全错"的教训与 6 题自查 → 收录数同步为最新 |'
$last = -1
for ($i = 0; $i -lt $lines.Count; $i++) { if ($lines[$i].StartsWith('| 2026-')) { $last = $i } }
$lines.Insert($last + 1, $log)

[System.IO.File]::WriteAllLines($p, $lines, (New-Object System.Text.UTF8Encoding($false)))
"写入完成：总行数=$($lines.Count)  收录=**$expect 份**"
